"""Deutsch — Anfängerstufe (200 Fragen)."""

T = {
"prophets_251": ("Wie heißt der Prophet des Islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "Isa"], "Der Prophet des Islam ist Muhammad ﷺ, der Sohn Abdullahs."),
"prophets_252": ("Isma'il und Ishaq sind die Söhne welches Propheten?", ["Ibrahim", "Musa", "Nuh", "Dawud"], "„Lob sei Allah, der mir trotz meines hohen Alters Isma'il und Ishaq geschenkt hat“ (14:39)."),
"prophets_253": ("Welchen Propheten erhob Allah zu Sich?", ["Isa", "Yunus", "Ayyub", "Idris"], "„Vielmehr hat Allah ihn zu Sich erhoben“ (4:158)."),
"prophets_254": ("Wer ist die Mutter des Propheten Isa?", ["Maryam", "Asiya", "Hajar", "Sara"], "Maryam, der eine ganze Sure des Korans gewidmet ist."),
"prophets_255": ("Wer ist der erste Mensch, den Allah erschuf?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam ist der erste Mensch; Allah lehrte ihn alle Namen."),
"prophets_256": ("Für welchen Propheten wurde das Feuer zu Kühle und Frieden?", ["Ibrahim", "Musa", "Yusuf", "Sulaiman"], "„O Feuer, sei Kühle und Frieden für Ibrahim.“"),
"prophets_257": ("Welcher Prophet trug einen Stab, der zu einer Schlange wurde?", ["Musa", "Harun", "Yahya", "Zakariyya"], "Allah fragte Musa: „Und was ist das in deiner rechten Hand?“"),
"prophets_258": ("Welcher Prophet träumte von elf Sternen, die sich niederwarfen?", ["Yusuf", "Ya'qub", "Ishaq", "Dawud"], "„O mein Vater, ich sah elf Sterne, die Sonne und den Mond.“"),
"prophets_259": ("Welcher Vogel brachte dem Propheten Sulayman eine Nachricht?", ["Der Wiedehopf", "Der Rabe", "Der Falke", "Die Taube"], "Der Wiedehopf sagte: „Ich bringe dir aus Saba eine sichere Nachricht“ (27:22)."),
"prophets_260": ("Welcher Prophet ist das Vorbild der Geduld in der Prüfung?", ["Ayyub", "Yunus", "Lut", "Shu'ayb"], "Ayyub rief seinen Herrn an und wurde als standhaft befunden."),
"prophets_261": ("Woraus erschuf Allah Adam?", ["Aus Erde", "Aus Licht", "Aus Feuer", "Aus Wind"], "„Er erschuf ihn aus Erde, dann sagte Er zu ihm: Sei!“ (3:59)."),
"prophets_262": ("Mit welchem Propheten sprach Allah direkt?", ["Musa", "Yusuf", "Yunus", "Salih"], "„Und Allah sprach mit Musa in direkter Rede.“"),
"prophets_263": ("Wie viele Propheten kommen nach Muhammad ﷺ?", ["Keiner: Er ist der letzte der Propheten", "Einer", "Drei", "Sieben"], "Muhammad ﷺ ist das Siegel der Propheten: Nach ihm kommt kein Prophet mehr."),
"prophets_264": ("Welcher Prophet wird der enge Freund (Khalil) Allahs genannt?", ["Ibrahim", "Musa", "Isa", "Nuh"], "Ibrahim ist der Vater der Propheten und der enge Freund des Allerbarmers."),
"prophets_265": ("Welcher Prophet heilte mit Allahs Erlaubnis den Blindgeborenen?", ["Isa", "Yahya", "Zakariyya", "Ilyas"], "„Und du heiltest den Blindgeborenen und den Aussätzigen mit Meiner Erlaubnis.“"),
"prophets_266": ("Mit welchem Propheten stimmten die Berge in das Lob Allahs ein?", ["Dawud", "Sulaiman", "Ayyub", "Yunus"], "„O ihr Berge, preist Allah gemeinsam mit ihm.“"),
"prophets_267": ("Welcher Prophet deutete den Traum des Königs von Ägypten?", ["Yusuf", "Harun", "Ilyas", "Shu'ayb"], "Yusuf deutete die sieben fetten und die sieben mageren Kühe (12:46-49)."),
"prophets_268": ("Wer ist der Vater des Propheten Yusuf?", ["Ya'qub", "Ishaq", "Ibrahim", "Lut"], "Yusuf ist der Sohn Ya'qubs, der selbst der Sohn Ishaqs ist."),
"prophets_269": ("Was teilte sich vor Musa und seinem Volk?", ["Das Meer, das sich teilte, um sie vor dem Pharao zu retten", "Ein Fluss Ägyptens", "Ein See in Madyan", "Ein Brunnen in der Wüste"], "„Und als Wir für euch das Meer teilten und euch retteten.“"),
"prophets_270": ("Was sagt man, nachdem man den Namen des Propheten ﷺ genannt hat?", ["„Allahs Segen und Frieden seien auf ihm“", "Nichts Besonderes", "„Danke“", "„Auf Wiedersehen“"], "Man erbittet Segen und Frieden für ihn: salla-Llahu alayhi wa sallam."),
"prophets_271": ("Welcher Prophet rief sein Volk vor der Flut sehr lange Zeit?", ["Nuh", "Hud", "Salih", "Shu'ayb"], "„Wir sandten Nuh zu seinem Volk: Warne dein Volk.“"),
"prophets_272": ("Sulayman ist der Sohn welches Propheten?", ["Dawud", "Ya'qub", "Ishaq", "Yunus"], "„Und Dawud schenkten Wir Sulayman – welch trefflicher Diener!“ (38:30)."),
"prophets_273": ("Welcher Prophet besiegte Jalut (Goliath)?", ["Dawud", "Sulayman", "Yusha'", "Ilyas"], "„Und Dawud tötete Jalut“ (2:251)."),
"prophets_274": ("An wie viele Propheten muss ein Muslim glauben?", ["An alle, ohne einen Unterschied zu machen", "Nur an den letzten", "Nur an drei", "Nur an die im Koran genannten"], "Ein Muslim glaubt an alle Propheten Allahs und macht keinen Unterschied zwischen ihnen."),
"prophets_275": ("Wen hat Allah laut Koran auserwählt?", ["Adam, Nuh, die Familie Ibrahims und die Familie Imrans", "Die Könige Ägyptens", "Die Stämme Medinas", "Das Volk von Saba"], "„Allah erwählte Adam und Nuh und die Familie Ibrahims und die Familie Imrans.“"),
"prophets_276": ("In welchem Land gewann der Prophet Yusuf das Vertrauen des Königs?", ["Ägypten", "Syrien (Sham)", "Jemen", "Irak"], "Yusuf erhielt in Ägypten eine feste Stellung, nachdem er den Traum des Königs gedeutet hatte."),
"prophets_277": ("Welcher Prophet wurde bei Nacht zur Al-Aqsa-Moschee geführt?", ["Muhammad ﷺ", "Musa", "Isa", "Ibrahim"], "„Gepriesen sei Der, Der Seinen Diener bei Nacht reisen ließ.“"),
"prophets_278": ("Welches Buch wurde dem Propheten Musa gegeben?", ["Die Tora", "Das Evangelium", "Die Psalmen", "Die Blätter Ibrahims"], "Allah gab Musa das Buch und ließ ihm Gesandte folgen."),
"prophets_279": ("Welches Buch wurde dem Propheten Isa gegeben?", ["Das Evangelium", "Die Tora", "Die Psalmen", "Der Koran"], "„Und Wir gaben ihm das Evangelium, in dem Rechtleitung und Licht sind.“"),
"prophets_280": ("Welches Buch wurde dem Propheten Dawud gegeben?", ["Die Psalmen (Zabur)", "Die Tora", "Das Evangelium", "Die Blätter Musas"], "„Und Wir gaben Dawud den Zabur.“"),
"prophets_281": ("Der Sohn welches Propheten willigte aus Gehorsam gegenüber Allah ein, geopfert zu werden?", ["Der Sohn Ibrahims", "Der Sohn Nuhs", "Der Bruder Musas", "Der Sohn Ya'qubs"], "„O mein Vater, tu, was dir befohlen wird: Du wirst mich geduldig finden.“"),
"prophets_282": ("Wohin legte die Mutter Musas ihr Baby, um es zu retten?", ["In den Fluss", "In eine Höhle", "Zu einer Nachbarin", "In die Wüste"], "„Wirf ihn in den Fluss: Wir werden ihn dir zurückbringen.“"),
"prophets_283": ("Was sagte Yunus in der Dunkelheit, was jeder Muslim wiederholt?", ["„Es gibt keinen Gott außer Dir, gepriesen seist Du, ich war einer der Ungerechten“", "„Gib mir Reichtum“", "„Mach mich zum König“", "„Mach mich stark“"], "Das Bittgebet von Yunus im Bauch des Fisches."),
"prophets_284": ("Wer ist der Vater des Propheten Muhammad ﷺ?", ["Abdullah", "Abu Talib", "Al-Abbas", "Hamza"], "Er ist Muhammad ﷺ, Sohn Abdullahs, Sohn Abd al-Muttalibs."),
"prophets_285": ("Wer ist die Mutter des Propheten Muhammad ﷺ?", ["Amina", "Khadija", "Aisha", "Fatima"], "Amina bint Wahb ist die Mutter des Propheten ﷺ."),
"prophets_286": ("Was sagte Isa, als er noch in der Wiege lag?", ["„Ich bin der Diener Allahs“", "„Ich bin ein König“", "„Ich bin ein Engel“", "Er sagte nichts"], "„Wahrlich, ich bin der Diener Allahs: Er hat mir die Schrift gegeben.“"),
"prophets_287": ("Welcher Prophet wurde zum Volk der Ad gesandt?", ["Hud", "Salih", "Lut", "Shu'ayb"], "„Und zu den Ad ihren Bruder Hud.“"),
"prophets_288": ("Welcher Prophet wurde mit der Kamelstute zu den Thamud gesandt?", ["Salih", "Hud", "Yunus", "Idris"], "„Und zu den Thamud ihren Bruder Salih: Dies ist die Kamelstute Allahs.“"),
"prophets_289": ("Welcher Prophet ist der Bruder Musas, der mit ihm gesandt wurde?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "„Und gib mir einen Helfer aus meiner Familie: Harun, meinen Bruder.“"),
"prophets_290": ("Welchen Titel gibt der Koran Muhammad ﷺ in Bezug auf die Propheten?", ["Das Siegel der Propheten", "Der erste der Propheten", "Der König der Propheten", "Der Schreiber der Propheten"], "„Muhammad ist der Gesandte Allahs und das Siegel der Propheten.“"),
"prophets_291": ("Was sagen die Engel im Koran zu Maryam?", ["Dass Allah sie auserwählt und gereinigt hat", "Dass sie Königin sein wird", "Dass sie reisen wird", "Dass sie lehren wird"], "„O Maryam, Allah hat dich auserwählt und dich gereinigt.“"),
"prophets_292": ("Wie rief Ayyub seinen Herrn in seiner Prüfung an?", ["„Mich hat Unheil getroffen, und Du bist der Barmherzigste“", "„Mach mich reich“", "„Bestrafe meine Feinde“", "„Mach mich zum König“"], "„Mich hat Unheil getroffen, und Du bist der Barmherzigste der Barmherzigen.“"),
"prophets_293": ("Was lehrte Allah Adam?", ["Alle Namen", "Das Schreiben", "Die Seefahrt", "Das Rechnen"], "„Und Er lehrte Adam alle Namen.“"),
"prophets_294": ("Welcher Prophet herrschte über ein Königreich, das niemand nach ihm haben sollte?", ["Sulaiman", "Dawud", "Yusuf", "Dhul-Qarnayn"], "„Schenke mir ein Königreich, wie es keinem nach mir zusteht.“"),
"prophets_295": ("Welcher Prophet wurde mit seiner Familie gerettet, außer seiner Frau?", ["Lut", "Nuh", "Hud", "Salih"], "„Zieh mit deiner Familie in einem Teil der Nacht fort… außer deiner Frau.“"),
"prophets_296": ("Wovor warnte Ibrahim sein Volk?", ["Vor der Anbetung von Götzen", "Vor dem Handel", "Vor dem Reisen", "Vor dem Schreiben"], "„Nehmt ihr Götzen zu Göttern?“"),
"prophets_297": ("Welches Wort bezeichnet jemanden, den Allah zu den Menschen gesandt hat?", ["Ein Gesandter (Rasul)", "Ein Kalif", "Ein Gefährte", "Ein Gelehrter"], "Ein Rasul ist ein von Allah Gesandter, dem eine Botschaft für die Menschen anvertraut wurde."),
"prophets_298": ("Als was sandte Allah den Propheten ﷺ laut Sure Al-Ahzab?", ["Als Zeugen, Verkünder froher Botschaft und Warner", "Als König und Richter", "Als Händler", "Als Dichter"], "„O Prophet, Wir haben dich als Zeugen, als Verkünder froher Botschaft und als Warner gesandt“ (33:45)."),
"prophets_299": ("Warum wurde Muhammad ﷺ laut Koran gesandt?", ["Als Barmherzigkeit für die Welten", "Um zu herrschen", "Um zu bauen", "Um Handel zu treiben"], "„Und Wir haben dich nur als Barmherzigkeit für die Welten gesandt.“"),
"prophets_300": ("Welchen Propheten nennt der Koran „einen dankbaren Diener“?", ["Nuh", "Lut", "Idris", "Ilyas"], "„Wahrlich, er war ein dankbarer Diener“ (17:3), gesagt über Nuh."),
"prophets_301": ("Welches Zeichen erhielt Zakariyya nach der Ankündigung seines Sohnes?", ["Drei Tage lang nicht mit den Menschen zu sprechen", "Einen Stern zu sehen", "Donner zu hören", "Auf dem Wasser zu gehen"], "„Dein Zeichen ist, dass du drei Tage lang nicht mit den Menschen sprechen wirst“ (3:41)."),
"prophets_302": ("In welcher Sprache wurde jeder Gesandte gesandt?", ["In der Sprache seines eigenen Volkes", "Nur auf Arabisch", "Auf Hebräisch", "In einer himmlischen Sprache"], "„Wir haben keinen Gesandten gesandt, außer in der Sprache seines Volkes.“"),
"prophets_303": ("Welche Sure erzählt die Geschichte eines Propheten von Anfang bis Ende?", ["Die Sure Yusuf", "Die Sure Al-Baqara", "Die Sure An-Nas", "Die Sure Al-Fatiha"], "„Wir erzählen dir die schönste der Geschichten“ – die Geschichte Yusufs."),
"prophets_304": ("Wie beschreibt der Koran Ibrahim in der Sure Maryam?", ["Als einen Mann der Wahrheit, einen Propheten", "Als einen König", "Als einen Schreiber", "Als einen Händler"], "„Er war ein Mann der Wahrheit, ein Prophet.“"),
"prophets_305": ("Welche Königin kam, um den Propheten Sulaiman zu sehen?", ["Die Königin von Saba", "Die Königin von Ägypten", "Die Königin von Babylon", "Die Königin des nördlichen Jemen"], "Sie ergab sich gemeinsam mit Sulaiman Allah, dem Herrn der Welten."),
"prophets_306": ("Welcher Prophet bat darum zu sehen, wie Allah die Toten wieder lebendig macht?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "„Mein Herr, zeige mir, wie Du die Toten lebendig machst.“"),
"prophets_307": ("Welcher Prophet reiste, um von einem wissenden Diener Allahs zu lernen?", ["Musa", "Yusuf", "Dawud", "Sulaiman"], "Musa reiste, bis er einen Diener Allahs traf, dem Er Wissen gegeben hatte."),
"prophets_308": ("Was lehrt die Sure Al-Ikhlas über Allah?", ["Dass Er Einer ist und niemand Ihm gleicht", "Dass Er Teilhaber hat", "Dass Er Seiner Schöpfung ähnelt", "Dass Er einen Sohn hat"], "„Sprich: Er ist Allah, Einer… und niemand ist Ihm gleich.“"),
"prophets_309": ("Wie nannten die Mekkaner den Propheten ﷺ vor der Offenbarung?", ["Al-Amin, der Vertrauenswürdige", "Der Reisende", "Der Dichter", "Der Richter"], "Seine Rechtschaffenheit war so bekannt, dass man ihn al-Amin nannte."),
"prophets_310": ("Wen stellt der Koran als das beste Vorbild dar, dem man folgen soll?", ["Den Gesandten Allahs ﷺ", "Die Könige", "Die Dichter", "Die Händler"], "„Ihr habt im Gesandten Allahs ein schönes Vorbild.“"),
"sira_251": ("In welcher Stadt wurde der Prophet ﷺ geboren?", ["Mekka", "Medina", "Jerusalem", "Ta'if"], "Der Prophet ﷺ wurde in Mekka geboren, im Stamm der Quraysh."),
"sira_252": ("In welche Stadt wanderte der Prophet ﷺ aus?", ["Medina", "Ta'if", "Kairo", "Damaskus"], "Die Hidschra führte von Mekka nach Medina, das damals Yathrib hieß."),
"sira_253": ("Wie heißt die Auswanderung von Mekka nach Medina?", ["Die Hidschra", "Die Pilgerfahrt", "Die Eroberung", "Der Vertrag"], "Die Hidschra markiert den Beginn des islamischen Kalenders."),
"sira_254": ("Wer ist die erste Frau des Propheten ﷺ?", ["Khadija", "Aisha", "Hafsa", "Sawda"], "Khadija bint Khuwaylid, die als Erste an ihn glaubte."),
"sira_255": ("In welcher Höhle versteckte sich der Prophet ﷺ während der Hidschra?", ["In der Höhle Thawr", "In der Höhle Hira", "In der Höhle Uhud", "In der Höhle Quba"], "Er verbarg sich dort drei Tage lang mit Abu Bakr, bevor er weiter nach Medina zog."),
"sira_256": ("Wie lautet das erste Wort, das dem Propheten ﷺ offenbart wurde?", ["„Lies“", "„Bete“", "„Steh auf“", "„Höre“"], "„Lies, im Namen deines Herrn, der erschuf.“"),
"sira_257": ("Welcher Engel brachte dem Propheten ﷺ die Offenbarung?", ["Jibril", "Mika'il", "Israfil", "Malik"], "Jibril ist der Engel, der damit beauftragt ist, die Offenbarung herabzubringen."),
"sira_258": ("In welcher Stadt befindet sich das Grab des Propheten ﷺ?", ["Medina", "Mekka", "Jerusalem", "Ta'if"], "Sein Grab befindet sich in Medina, neben seiner Moschee."),
"sira_259": ("Aus welchem Stamm stammte der Prophet ﷺ?", ["Quraysh", "Aws", "Khazraj", "Thaqif"], "Der Prophet ﷺ gehörte zu den Quraysh, dem Stamm von Mekka."),
"sira_260": ("Wie nennt man die Gefährten des Propheten ﷺ?", ["Die Sahaba", "Die Tabi'un", "Nur die Ansar", "Die Qurra"], "Die Sahaba sind diejenigen, die den Propheten ﷺ gesehen haben und an ihn glaubten."),
"sira_261": ("Wer begleitete den Propheten ﷺ bei der Hidschra?", ["Abu Bakr", "Umar", "Uthman", "Bilal"], "Abu Bakr war während der Hidschra sein Gefährte in der Höhle."),
"sira_262": ("Wer war der Gebetsrufer des Propheten ﷺ?", ["Bilal", "Anas", "Zayd", "Salman"], "Bilal ibn Rabah rief in Medina zum Gebet."),
"sira_263": ("Wie heißt die erste Schlacht des Islam?", ["Badr", "Uhud", "Khaybar", "Hunayn"], "Badr ist die erste große Schlacht, im zweiten Jahr der Hidschra."),
"sira_264": ("Wie nennt man diejenigen, die von Mekka nach Medina auswanderten?", ["Die Muhajirun", "Die Ansar", "Die Tabi'un", "Die Gefährten aus Ta'if"], "Die Muhajirun sind die Auswanderer; die Ansar sind diejenigen, die sie aufnahmen."),
"sira_265": ("Wie nennt man die Bewohner Medinas, die die Auswanderer aufnahmen?", ["Die Ansar", "Die Muhajirun", "Die Quraysh", "Die Tabi'un"], "Die Ansar, „die Helfer“, sind die Aws und die Khazraj von Medina."),
"sira_266": ("Was baute der Prophet ﷺ zuerst in Medina?", ["Eine Moschee", "Einen Markt", "Einen Palast", "Eine Mauer"], "Er baute seine Moschee, sobald er in Medina ankam."),
"sira_267": ("Welche Tochter des Propheten ﷺ heiratete Ali?", ["Fatima", "Ruqayya", "Zaynab", "Umm Kulthum"], "Fatima, die Tochter des Propheten ﷺ, heiratete Ali ibn Abi Talib."),
"sira_268": ("Wer war der erste Kalif nach dem Propheten ﷺ?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "Abu Bakr as-Siddiq war der erste Kalif."),
"sira_269": ("Wie hieß Medina früher?", ["Yathrib", "Bakka", "Ta'if", "Khaybar"], "Yathrib erhielt den Namen Madinat an-Nabi, die Stadt des Propheten ﷺ."),
"sira_270": ("Wie alt war der Prophet ﷺ bei der ersten Offenbarung?", ["Vierzig Jahre", "Zwanzig", "Sechzig", "Dreißig"], "Die Offenbarung kam zu ihm, als er vierzig Jahre alt war."),
"sira_271": ("In welcher Stadt steht die Ka'ba?", ["Mekka", "Medina", "Jerusalem", "Damaskus"], "Die Ka'ba steht in der Mitte der Heiligen Moschee in Mekka."),
"sira_272": ("In welcher Stadt steht die Al-Aqsa-Moschee?", ["Jerusalem", "Mekka", "Medina", "Kairo"], "Die Al-Aqsa-Moschee befindet sich in Jerusalem (al-Quds)."),
"sira_273": ("Welcher Onkel des Propheten ﷺ beschützte ihn in Mekka?", ["Abu Talib", "Abu Lahab", "Al-Abbas", "Abu Sufyan"], "Abu Talib, der Vater Alis, beschützte seinen Neffen gegen die Quraysh."),
"sira_274": ("Welchen Beruf hatte Khadija, die erste Frau des Propheten ﷺ?", ["Händlerin", "Ärztin", "Dichterin", "Weberin"], "Khadija war eine angesehene Händlerin in Mekka."),
"sira_275": ("Wie heißt die letzte Pilgerfahrt des Propheten ﷺ?", ["Die Abschiedspilgerfahrt", "Die erste Pilgerfahrt", "Die Pilgerfahrt der Eroberung", "Die kleine Pilgerfahrt"], "Die Abschiedspilgerfahrt fand im Jahr 10 der Hidschra statt."),
"sira_276": ("Wie heißt die Erzählung vom Leben des Propheten ﷺ?", ["Die Sira", "Die Sunna", "Der Tafsir", "Das Fiqh"], "Die Sira ist die Erzählung seines Lebens; die Sunna ist das, was er sagte und tat."),
"sira_277": ("Wie nennt man einen vom Propheten ﷺ überlieferten Ausspruch?", ["Einen Hadith", "Eine Sure", "Einen Vers", "Ein Bittgebet"], "Ein Hadith ist ein Ausspruch, eine Handlung oder eine Billigung des Propheten ﷺ."),
"sira_278": ("Welche beiden Hadith-Sammlungen gelten als die zuverlässigsten?", ["Sahih al-Buchari und Sahih Muslim", "Zwei Gedichtsammlungen", "Zwei Geschichtsbücher", "Zwei Wörterbücher"], "Zusammen nennt man sie „die beiden Sahih“."),
"sira_279": ("Welcher Kalif ließ den Koran abschreiben und in die Provinzen schicken?", ["Uthman", "Abu Bakr", "Umar", "Ali"], "Uthman ließ offizielle Abschriften anfertigen und in die wichtigsten Städte schicken."),
"sira_280": ("Wie viele Kalifen sind „die rechtgeleiteten Kalifen“?", ["Vier", "Zwei", "Sieben", "Zwölf"], "Abu Bakr, Umar, Uthman und Ali."),
"sira_281": ("In welche Richtung beten die Muslime?", ["Zur Ka'ba in Mekka", "Nach Jerusalem", "Nach Osten", "Nach Medina"], "Die Qibla ist die Richtung der Ka'ba."),
"sira_282": ("Wie heißt diese Gebetsrichtung?", ["Die Qibla", "Der Mihrab", "Der Minbar", "Das Minarett"], "Die Qibla ist die Richtung; der Mihrab ist die Nische, die sie anzeigt."),
"sira_283": ("Wie heißt der Ort, an dem die Muslime gemeinsam beten?", ["Die Moschee", "Die Schule", "Der Markt", "Die Bibliothek"], "Die Masjid ist der Ort der Niederwerfung, die Moschee."),
"sira_284": ("Wie heißt der Ruf zum Gebet?", ["Der Adhan", "Der Takbir", "Der Tasbih", "Der Dhikr"], "Der Adhan ist der Gebetsruf; wer ihn ausruft, ist der Muezzin."),
"sira_285": ("An welchem Tag versammeln sich die Muslime zum großen Gebet?", ["Am Freitag", "Am Samstag", "Am Sonntag", "Am Montag"], "Das Freitagsgebet (al-Jumu'a) versammelt die Gemeinschaft jede Woche."),
"sira_286": ("Wie nennt man die Person, die das Gebet leitet?", ["Den Imam", "Den Muezzin", "Den Richter", "Den Hafiz"], "Der Imam ist derjenige, hinter dem sich die Gemeinde zum Gebet aufstellt."),
"sira_287": ("Wie nennt man jemanden, der den ganzen Koran auswendig gelernt hat?", ["Einen Hafiz", "Einen Imam", "Einen Muezzin", "Einen Richter"], "Ein Hafiz ist jemand, der den ganzen Koran im Gedächtnis bewahrt."),
"sira_288": ("Welcher Gefährte ist als der größte Überlieferer von Hadithen bekannt?", ["Abu Hurayra", "Bilal", "Salman", "Anas"], "Abu Hurayra verbrachte die letzten Jahre des Propheten ﷺ an seiner Seite."),
"sira_289": ("Welcher Kalif wird as-Siddiq, „der Wahrhaftige“, genannt?", ["Abu Bakr", "Umar", "Uthman", "Ali"], "Abu Bakr as-Siddiq, der erste freie Mann, der glaubte."),
"sira_290": ("Welcher Kalif wird al-Faruq genannt?", ["Umar ibn al-Khattab", "Abu Bakr", "Uthman", "Ali"], "Umar, der Wahrheit von Falschheit unterschied, erhielt diesen Titel."),
"sira_291": ("Welcher Kalif ließ den Koran in einem einzigen Band zusammenstellen?", ["Abu Bakr", "Mu'awiya", "Khalid", "Bilal"], "Abu Bakr befahl, das Aufgeschriebene zusammenzutragen."),
"sira_292": ("Welcher Großvater zog den Propheten ﷺ als Kind auf?", ["Abd al-Muttalib", "Abu Sufyan", "Al-Walid", "Utba"], "Sein Großvater Abd al-Muttalib nahm sich nach seiner Geburt seiner an."),
"sira_293": ("Wie erinnert der Koran an die Kindheit des Propheten ﷺ?", ["Allah fand ihn als Waise und gab ihm Zuflucht", "Er war ein König", "Er war von Kindheit an reich", "Er lebte allein in der Wüste"], "„Fand Er dich nicht als Waise und gab dir Zuflucht?“ (93:6)."),
"sira_294": ("Welche Schlacht kam nach Badr?", ["Uhud", "Die Grabenschlacht", "Hunayn", "Tabuk"], "Im folgenden Jahr kam die Schlacht von Uhud, nahe Medina."),
"sira_295": ("Was gruben die Muslime rund um Medina, um die Stadt zu verteidigen?", ["Einen Graben (al-Khandaq)", "Einen Brunnen", "Einen Tunnel", "Einen Kanal"], "Sie hoben einen Graben aus, der der Grabenschlacht ihren Namen gab."),
"sira_296": ("Wessen Tochter war Aisha, die Frau des Propheten ﷺ?", ["Die Tochter Abu Bakrs", "Die Tochter Umars", "Die Tochter Uthmans", "Die Tochter Alis"], "Aisha war die Tochter von Abu Bakr as-Siddiq."),
"sira_297": ("Wie nennt der Koran die Frauen des Propheten ﷺ?", ["Die Mütter der Gläubigen", "Die Dienerinnen", "Die Reisegefährtinnen", "Die Auswanderinnen"], "„Und seine Frauen sind ihre Mütter“ (33:6)."),
"sira_298": ("Welcher Gefährte war zugleich Cousin und Schwiegersohn des Propheten ﷺ?", ["Ali ibn Abi Talib", "Bilal", "Salman", "Zayd"], "Ali, der Cousin des Propheten ﷺ, heiratete dessen Tochter Fatima."),
"sira_299": ("Wie heißt die Moschee des Propheten ﷺ in Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Aqsa", "Quba"], "Die Prophetenmoschee, an-Nabawi, steht in Medina."),
"sira_300": ("Wie heißt das Reittier der Nachtreise des Propheten ﷺ?", ["Al-Buraq", "Al-Adba", "Asch-Schaqra", "Al-Qaswa"], "Das Reittier der Nachtreise heißt al-Buraq."),
"faith_151": ("Wie viele Säulen hat der Islam?", ["Fünf", "Drei", "Sechs", "Zehn"], "Fünf: das Glaubensbekenntnis, das Gebet, die Zakat, das Fasten und die Pilgerfahrt."),
"faith_152": ("Was ist die erste Säule des Islam?", ["Das Glaubensbekenntnis (Shahada)", "Das Fasten", "Die Pilgerfahrt", "Die Zakat"], "Man tritt in den Islam ein, indem man bezeugt, dass es keinen Gott außer Allah gibt und Muhammad ﷺ Sein Gesandter ist."),
"faith_153": ("Wie viele Pflichtgebete verrichtet ein Muslim jeden Tag?", ["Fünf", "Drei", "Sieben", "Zwei"], "Fünf Gebete, verteilt von der Morgendämmerung bis zur Nacht."),
"faith_154": ("In welchem Monat fasten die Muslime?", ["Ramadan", "Rajab", "Sha'ban", "Shawwal"], "„Der Monat Ramadan, in dem der Koran herabgesandt wurde“ (2:185)."),
"faith_155": ("Wie heißt die Pflichtabgabe im Islam?", ["Zakat", "Du'a", "Dhikr", "Tawaf"], "Die Zakat ist der Anteil des Vermögens, der jedes Jahr abgegeben wird."),
"faith_156": ("Wie heißt die große Pilgerfahrt nach Mekka?", ["Der Hadsch", "Der Sa'y", "Der Dhikr", "Der Suhur"], "Der Hadsch ist die Pilgerfahrt, die jeder, der dazu in der Lage ist, einmal im Leben unternimmt."),
"faith_157": ("Wie viele Glaubensartikel (Arkan al-Iman) gibt es?", ["Sechs", "Vier", "Fünf", "Sieben"], "Der Glaube an Allah, Seine Engel, Seine Bücher, Seine Gesandten, den Jüngsten Tag und die Vorherbestimmung."),
"faith_158": ("An wie viele Götter glaubt ein Muslim?", ["An einen einzigen", "An zwei", "An drei", "An viele"], "„Sprich: Er ist Allah, der Eine“ (112:1)."),
"faith_159": ("Wie nennen die Muslime Gott auf Arabisch?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah ist der Name des Schöpfers auf Arabisch."),
"faith_160": ("Wie heißt das heilige Buch der Muslime?", ["Der Koran", "Die Tawrat", "Das Injil", "Der Zabur"], "Der Koran ist das Buch, das dem Propheten Muhammad ﷺ offenbart wurde."),
"faith_161": ("Wie heißt das Haus Allahs, das in Mekka gebaut wurde?", ["Die Ka'ba", "Die Rawda", "Der Maqam", "Der Hijr"], "„Das erste Haus, das für die Menschen errichtet wurde, ist das in Bakka“ (3:96)."),
"faith_162": ("Was sagt ein Muslim, bevor er zu essen beginnt?", ["Bismillah", "Amin", "Subhan Allah", "Allahumma"], "Der Prophet ﷺ lehrte einen Jungen: „Sag Bismillah und iss mit der rechten Hand.“"),
"faith_163": ("Wie begrüßen sich die Muslime?", ["As-salamu alaykum", "Al-hamdu lillah", "Bismillah", "Allahu akbar"], "„As-salamu alaykum“ bedeutet: Friede sei mit euch."),
"faith_164": ("Was antwortet man auf „as-salamu alaykum“?", ["Wa alaykum as-salam", "Bismillah", "Amin", "Subhan Allah"], "Man erwidert den Gruß: „und mit euch sei Friede“."),
"faith_165": ("Wie heißt das Fest direkt nach dem Monat Ramadan?", ["Eid al-Fitr", "Eid al-Adha", "Laylat al-Qadr", "Ashura"], "Eid al-Fitr, das Fest des Fastenbrechens."),
"faith_166": ("Wie heißt das Opferfest?", ["Eid al-Adha", "Eid al-Fitr", "Der Mawlid", "Laylat al-Qadr"], "Eid al-Adha fällt in die Tage der Pilgerfahrt."),
"faith_167": ("Wie heißen die Geschöpfe Allahs, die Ihm immer gehorchen und sich nie widersetzen?", ["Die Engel", "Die Dschinn", "Die Propheten", "Die Gefährten"], "Die Engel führen aus, was Allah befiehlt, und widersetzen sich Ihm nie."),
"faith_168": ("Wie heißt das Paradies auf Arabisch?", ["Al-Janna", "As-Salat", "Ad-Du'a", "Al-Adhan"], "Al-Janna, wörtlich „der Garten“, ist die Heimstatt, die den Gläubigen versprochen ist."),
"faith_169": ("Wie heißt die Waschung mit Wasser, die man vor dem Gebet vornimmt?", ["Die Gebetswaschung (Wudu)", "Der Tawaf", "Der Dhikr", "Der Sa'y"], "Der Wudu ist die Reinigung, die dem Gebet vorausgeht."),
"faith_170": ("Wie heißt eine Einheit des Gebets?", ["Eine Rak'a", "Eine Sure", "Ein Adhan", "Ein Tawaf"], "Eine Rak'a umfasst das Stehen, die Verbeugung und die Niederwerfungen."),
"faith_171": ("Welche Sure wird in jeder Gebetseinheit rezitiert?", ["Al-Fatiha", "Al-Ikhlas", "An-Nas", "Al-Kawthar"], "Al-Fatiha, die eröffnende Sure, wird in jeder Rak'a rezitiert."),
"faith_172": ("Wie nennt man das, was im Islam erlaubt ist?", ["Halal", "Haram", "Sunna", "Fard"], "Halal bedeutet das, was erlaubt ist."),
"faith_173": ("Wie nennt man das, was im Islam verboten ist?", ["Haram", "Halal", "Mubah", "Nafila"], "Haram bedeutet das, was verboten ist."),
"faith_174": ("Welches Fleisch verbietet der Koran?", ["Schweinefleisch", "Lammfleisch", "Rindfleisch", "Hühnerfleisch"], "„Verboten hat Er euch Verendetes, Blut und Schweinefleisch“ (2:173)."),
"faith_175": ("Welches Getränk sollen wir laut Koran meiden?", ["Wein und jedes berauschende Getränk", "Milch", "Honig", "Regenwasser"], "„Wein, Glücksspiel… sind ein Gräuel, so meidet sie“ (5:90)."),
"faith_176": ("Was sagt jemand, der niest, wie der Prophet ﷺ es gelehrt hat?", ["Al-hamdu lillah", "Bismillah", "Allahu akbar", "Amin"], "„Wenn einer von euch niest, soll er sagen: al-hamdu lillah.“"),
"faith_177": ("Wie sagt man „das Gebet“ auf Arabisch?", ["As-Salat", "As-Sawm", "Az-Zakat", "Al-Hadsch"], "As-Salat ist das rituelle Gebet des Muslims."),
"faith_178": ("Wie nennt man es, wenn man Allah mit eigenen Worten um etwas bittet?", ["Du'a", "Tawaf", "Adhan", "Sa'y"], "Du'a ist das Bittgebet, das Anrufen Allahs."),
"faith_179": ("Was bedeutet „al-hamdu lillah“?", ["Lob sei Allah", "Allah ist der Größte", "Im Namen Allahs", "Gepriesen sei Allah"], "Es ist der zweite Vers von Al-Fatiha: „Lob sei Allah, dem Herrn der Welten“ (1:2)."),
"faith_180": ("Was bedeutet das Wort „Islam“?", ["Hingabe an Allah", "Reichtum", "Reise", "Wissen"], "Islam kommt von einer Wurzel, die „sich hingeben“ und „in Frieden sein“ bedeutet."),
"faith_181": ("Was bedeutet das Wort „Muslim“?", ["Jemand, der sich Allah hingibt", "Jemand, der reist", "Jemand, der lehrt", "Jemand, der baut"], "Ein Muslim ist jemand, der sich Allah allein hingibt."),
"faith_182": ("Wer hat laut Koran die Himmel und die Erde erschaffen?", ["Allah", "Die Engel", "Die Propheten", "Die Sonne"], "„Lob sei Allah, Der die Himmel und die Erde erschaffen hat“ (6:1)."),
"faith_183": ("Wie viele Namen Allahs nennt der Hadith?", ["Neunundneunzig", "Zehn", "Fünfzig", "Tausend"], "„Allah hat neunundneunzig Namen, hundert weniger einen.“"),
"faith_184": ("Was tun die Engel, die „edle Schreiber“ genannt werden?", ["Sie schreiben unsere Taten auf", "Sie tragen den Regen", "Sie bewachen die Ka'ba", "Sie lehren Arabisch"], "„Edle Schreiber, die wissen, was ihr tut“ (82:11-12)."),
"faith_185": ("Welche Nacht beschreibt der Koran als besser als tausend Monate?", ["Laylat al-Qadr", "Die Nacht auf Freitag", "Die Nacht des Eid", "Die erste Nacht des Ramadan"], "„Die Nacht der Bestimmung ist besser als tausend Monate“ (97:3)."),
"faith_186": ("Wie heißt der Glaube an einen einzigen Gott?", ["Tawhid", "Tawaf", "Tayammum", "Tarawih"], "Tawhid ist die Einheit Allahs, das Herzstück der Botschaft jedes Propheten."),
"faith_187": ("Wie nennt man es, wenn man Allah in der Anbetung jemanden beigesellt?", ["Shirk", "Dhikr", "Du'a", "Sabr"], "Shirk ist die Beigesellung: etwas neben Allah anzubeten."),
"faith_188": ("Wie heißt der Tag, an dem alle gerichtet werden?", ["Der Tag der Auferstehung", "Der Tag des Eid", "Der Freitag", "Der erste Tag des Ramadan"], "Yawm al-Qiyama, der Tag der Auferstehung, an dem jeder seine Taten sehen wird."),
"faith_189": ("Wie viele Monate hat das Jahr laut Koran?", ["Zwölf", "Zehn", "Vierzehn", "Sechs"], "„Die Zahl der Monate bei Allah ist zwölf“ (9:36)."),
"faith_190": ("Wie viele Niederwerfungen gibt es in einer einzigen Rak'a?", ["Zwei", "Eine", "Drei", "Vier"], "Jede Rak'a enthält zwei Niederwerfungen."),
"quran_151": ("Wie viele Suren enthält der Koran?", ["Hundertvierzehn", "Sechzig", "Zweihundert", "Dreißig"], "Der Koran hat 114 Suren, von Al-Fatiha bis An-Nas."),
"quran_152": ("Welche ist die erste Sure des Korans?", ["Al-Fatiha", "Al-Baqara", "An-Nas", "Ya-Sin"], "Al-Fatiha, „die Eröffnende“, ist die erste Sure."),
"quran_153": ("Was bedeutet das Wort „Koran“?", ["Die Rezitation, die Lesung", "Der Weg", "Das Licht", "Der Garten"], "Koran kommt von einer Wurzel, die „lesen“ und „rezitieren“ bedeutet."),
"quran_154": ("Über wie viele Jahre wurde der Koran ungefähr herabgesandt?", ["Etwa dreiundzwanzig Jahre", "In einer einzigen Nacht", "Hundert Jahre", "Drei Jahre"], "Die Offenbarung kam über etwa dreiundzwanzig Jahre herab."),
"quran_155": ("Wie nennt man einen Vers des Korans?", ["Eine Aya", "Eine Sure", "Einen Juz'", "Einen Hadith"], "Jeder nummerierte Satz des Korans ist eine Aya, ein „Zeichen“."),
"quran_156": ("Wie nennt man ein Kapitel des Korans?", ["Eine Sure", "Eine Aya", "Einen Juz'", "Eine Khutba"], "Der Koran ist in Suren unterteilt, jede mit ihrem eigenen Namen."),
"quran_157": ("Welche ist die längste Sure des Korans?", ["Al-Baqara", "Al-Fatiha", "Al-Kawthar", "An-Nas"], "Al-Baqara ist die längste Sure des Korans."),
"quran_158": ("Welche ist die kürzeste Sure des Korans?", ["Al-Kawthar", "Al-Baqara", "Al Imran", "An-Nisa"], "Al-Kawthar hat nur drei Verse."),
"quran_159": ("Welcher Satz eröffnet fast jede Sure?", ["Im Namen Allahs, des Allerbarmers, des Barmherzigen", "Lob sei Allah", "Allah ist der Größte", "Es gibt keinen Gott außer Allah"], "Die Basmala eröffnet 113 der 114 Suren."),
"quran_160": ("Wessen Rede ist der Koran?", ["Die Rede Allahs", "Die Rede des Propheten ﷺ", "Die Rede des Engels Jibril", "Die Rede der Gefährten"], "Der Koran nennt sich selbst „die Rede Allahs“ (Kalam Allah) in 9:6."),
"quran_161": ("In wie viele Teile (Juz') ist der Koran eingeteilt?", ["Dreißig", "Zehn", "Fünfzig", "Hundert"], "Der Koran ist in dreißig Juz' eingeteilt, einen für jede Nacht des Ramadan."),
"quran_162": ("Welche Sure trägt den Namen einer Frau?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "Sure 19 trägt den Namen Maryams."),
"quran_163": ("Wie heißen die beiden letzten Suren, mit denen man Schutz sucht?", ["Al-Mu'awwidhatan", "Al-Mathani", "Al-Mufassal", "Al-Hawamim"], "Al-Falaq und An-Nas heißen al-Mu'awwidhatan, „die beiden Schutzsuren“."),
"quran_164": ("Welches Wort eröffnet die Sure Al-Fatiha nach der Basmala?", ["Al-hamdu", "Qul", "Iqra'", "Inna"], "„Al-hamdu lillahi rabbi l-alamin“ eröffnet Al-Fatiha."),
"quran_165": ("Wie heißt die Erklärung der Bedeutung des Korans?", ["Tafsir", "Tajwid", "Hifz", "Tawaf"], "Der Tafsir ist die Wissenschaft, die die Bedeutung der Verse erklärt."),
"quran_166": ("Welche Sure beginnt nicht mit der Basmala?", ["At-Tawba", "Al-Fatiha", "Al-Ikhlas", "An-Nasr"], "At-Tawba ist die einzige Sure, die nicht mit der Basmala beginnt."),
"quran_167": ("Wie nennt man jemanden, der den Koran laut rezitiert?", ["Einen Qari'", "Einen Muezzin", "Einen Imam", "Einen Khatib"], "Der Qari' ist der Rezitator des Korans."),
"quran_168": ("In welcher Sure steht der Thronvers?", ["Al-Baqara", "Al-Kahf", "Ya-Sin", "Al-Mulk"], "Der Thronvers ist Vers 255 der Sure Al-Baqara."),
"quran_169": ("Was bedeutet „An-Nur“, der Titel der 24. Sure?", ["Das Licht", "Die Nacht", "Der Wind", "Der Berg"], "An-Nur bedeutet „das Licht“."),
"quran_170": ("Welche Sure heißt „Der Allerbarmer“?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "As-Saff"], "Sure 55 heißt Ar-Rahman."),
"quran_171": ("Welche Sure ist nach der Höhle benannt?", ["Al-Kahf", "Al-Fil", "An-Naml", "Al-Baqara"], "Al-Kahf bedeutet „die Höhle“."),
"quran_172": ("Was bedeutet „An-Nisa“, der Titel der 4. Sure?", ["Die Frauen", "Die Männer", "Die Kinder", "Die Reisenden"], "An-Nisa bedeutet „die Frauen“."),
"quran_173": ("Was bedeutet „Al-Ma'ida“, der Titel der 5. Sure?", ["Der gedeckte Tisch", "Der Berg", "Das Eisen", "Die Morgendämmerung"], "Al-Ma'ida bedeutet „der gedeckte Tisch“."),
"quran_174": ("Welcher Prophet gibt der 71. Sure ihren Namen?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "Sure 71 heißt Nuh."),
"quran_175": ("Wie viele Verse hat die Sure Al-Fatiha?", ["Sieben", "Drei", "Zehn", "Zwanzig"], "Al-Fatiha hat sieben Verse."),
"quran_176": ("Wo ist der Koran laut seiner eigenen Aussage bewahrt?", ["Auf einer wohlverwahrten Tafel", "In einer Höhle", "In einer Truhe", "Auf einem Berg"], "„Es ist ein ruhmvoller Koran, auf einer wohlverwahrten Tafel“ (85:21-22)."),
"quran_177": ("Welche Sure ist nach dem Mond benannt?", ["Al-Qamar", "Ash-Shams", "An-Najm", "Al-Layl"], "Al-Qamar bedeutet „der Mond“."),
"quran_178": ("Welche Sure ist nach dem Tag der Auferstehung benannt?", ["Al-Qiyama", "Al-Fath", "Al-Hashr", "As-Saff"], "Sure 75 heißt Al-Qiyama."),
"quran_179": ("Welcher Prophet gibt der 14. Sure ihren Namen?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "Sure 14 heißt Ibrahim."),
"quran_180": ("Was bedeutet „Al-Hadid“, der Titel der 57. Sure?", ["Das Eisen", "Das Gold", "Das Holz", "Der Stein"], "Al-Hadid bedeutet „das Eisen“."),
"virtues_101": ("Wie sollen wir laut Koran mit unseren Eltern sprechen?", ["Mit respektvollen Worten, ohne auch nur „Uff“ zu sagen", "Lauter als sie", "Indem wir immer schweigen", "Nur freitags"], "„Sag nicht Uff zu ihnen, und sprich zu ihnen ehrerbietige Worte“ (17:23)."),
"virtues_102": ("Wie nennt man eine Gabe, die man freiwillig aus Güte gibt?", ["Sadaqa", "Zakat", "Tawaf", "Adhan"], "Sadaqa ist die freiwillige Spende, ob klein oder groß."),
"virtues_103": ("Was rät der Prophet ﷺ beim Sprechen dem, der an Allah und den Jüngsten Tag glaubt?", ["Er soll Gutes sagen oder schweigen", "Er soll viel reden", "Er soll nie sprechen", "Er soll nur mit seiner Familie sprechen"], "„Wer an Allah und den Jüngsten Tag glaubt, soll Gutes sagen oder schweigen.“"),
"virtues_104": ("Wie sollen wir laut dem Propheten ﷺ unseren Nachbarn behandeln?", ["Großzügig zu ihm sein", "Ihn meiden", "Nie mit ihm sprechen", "Ihn bitten wegzuziehen"], "„Wer an Allah und den Jüngsten Tag glaubt, soll großzügig zu seinem Nachbarn sein.“"),
"virtues_105": ("Mit wem ist Allah laut Koran?", ["Mit den Geduldigen", "Mit den Reichsten", "Mit den Stärksten", "Mit den Schnellsten"], "„Wahrlich, Allah ist mit den Geduldigen“ (2:153)."),
"virtues_106": ("Was verbietet der Koran im Umgang mit der Waise?", ["Sie hart zu behandeln", "Ihr das Lesen beizubringen", "Sie zum Essen einzuladen", "Mit ihr zu spielen"], "„Was nun die Waise angeht, so unterdrücke sie nicht“ (93:9)."),
"virtues_107": ("Welche Art von Rede sollen wir laut Koran meiden?", ["Falsche Rede", "Sanfte Rede", "Worte des Dankes", "Worte des Grußes"], "„Und meidet die falsche Rede“ (22:30)."),
"virtues_108": ("Wem sollen wir laut Koran neben dem nahen Verwandten sein Recht geben?", ["Dem Armen und dem Reisenden", "Dem König und dem Richter", "Dem Händler", "Dem Dichter"], "„Gib dem Verwandten sein Recht, und dem Armen und dem Reisenden“ (17:26)."),
"virtues_109": ("Was verspricht Allah dem, der Ihm dankt?", ["Ihm noch mehr zu geben", "Ihn reisen zu lassen", "Ihn berühmt zu machen", "Ihn zum König zu machen"], "„Wenn ihr dankbar seid, werde Ich euch gewiss noch mehr geben“ (14:7)."),
"virtues_110": ("Wie sagt man „Geduld“ auf Arabisch?", ["As-Sabr", "Ash-Shukr", "As-Sidq", "Al-Haya'"], "As-Sabr ist die Standhaftigkeit in der Not und im Gehorsam."),
"faith_191": ("Wie nennt man das Gedenken an Allah, bei dem man Sein Lob wiederholt?", ["Dhikr", "Hadsch", "Sa'y", "Tayammum"], "Dhikr ist das Gedenken an Allah mit der Zunge und dem Herzen."),
"faith_192": ("Welcher ist der erste Monat des islamischen Jahres?", ["Muharram", "Ramadan", "Shawwal", "Rajab"], "Das Hidschra-Jahr beginnt mit dem Monat Muharram."),
"faith_193": ("Wie nennt man die Rückkehr zu Allah nach einer Sünde?", ["Tawba", "Tawaf", "Tajwid", "Tarawih"], "Tawba ist die Reue: bereuen, aufhören und zu Allah zurückkehren."),
"faith_194": ("Wer versorgt jedes Geschöpf auf der Erde?", ["Allah", "Die Könige", "Die Händler", "Die Engel"], "„Es gibt kein Geschöpf auf der Erde, dessen Versorgung nicht Allah obliegt“ (11:6)."),
"faith_195": ("In welcher Stadt wird die Pilgerfahrt vollzogen?", ["In Mekka", "In Medina", "In Jerusalem", "In Kairo"], "Der Hadsch findet in Mekka und an seinen heiligen Stätten statt."),
"faith_196": ("Wie nennt man jemanden, der die Pilgerfahrt vollzieht?", ["Einen Hadschi (Pilger)", "Einen Imam", "Einen Qari'", "Einen Muezzin"], "Der Pilger wird Hadschi genannt."),
"faith_197": ("Was weiß Allah laut Koran, selbst wenn es verborgen ist?", ["Was in den Herzen ist", "Nur die sichtbaren Taten", "Nur die gesprochenen Worte", "Nichts Verborgenes"], "„Ob ihr verbergt, was in eurer Brust ist, oder es offenlegt, Allah weiß es“ (3:29)."),
"faith_198": ("Wem wurde laut Koran das Fasten vorgeschrieben?", ["Den Gläubigen, wie denen vor ihnen", "Nur den Reisenden", "Nur den Gelehrten", "Nur den Kindern"], "„O die ihr glaubt, das Fasten ist euch vorgeschrieben, so wie es denen vor euch vorgeschrieben war“ (2:183)."),
"faith_199": ("Wie heißt das große Gemeinschaftsgebet am Freitag?", ["Salat al-Jumu'a", "Salat al-Eid", "Salat al-Witr", "Salat ad-Duha"], "Salat al-Jumu'a versammelt die Muslime am Freitag zur Mittagszeit."),
"faith_200": ("Wie sagt man „das Fasten“ auf Arabisch?", ["As-Sawm", "As-Salat", "Az-Zakat", "Al-Adhan"], "As-Sawm ist das Fasten, die vierte Säule des Islam."),
}
